const original = $('Extract DM Data').first().json;

let contactRows = [];
let historyRows = [];

try { contactRows = $('Get Contact Row').all() || []; } catch(e) {}
try { historyRows = $('Get DM Chat History').all() || []; } catch(e) {}

const contact = contactRows.find(r => r.json && r.json['session_id'])?.json || {};

let chatHistory = '';
if (historyRows.length > 0) {
  chatHistory = historyRows
    .map(r => r.json['Chat History'] || r.json['text'])
    .filter(Boolean)
    .join('\n');
}

const bookingLink = 'https://cal.com/{{BOOKING_SLUG}}';
const bookingAlreadySent = chatHistory.includes(bookingLink) ? 'Yes' : 'No';

return [{
  json: {
    ...original,
    contactExists: !!contact['session_id'],
    contactName: contact['name'] || '',
    contactEmail: contact['email'] || '',
    contactPhone: contact['phone'] || '',
    serviceType: contact['service_type'] || '',
    existingSummary: contact['summary'] || '',
    existingInterest: contact['interest'] || 'Pending',
    existingLastMessage: contact['last_message_sent'] || '',
    chatHistory: chatHistory || '',
    hasHistory: chatHistory ? 'Yes' : 'No',
    bookingAlreadySent,
    bookingLink
  }
}];

const raw = $input.first().json.output || '';
const base = $('Merge Context').first().json;

let reply = '';
let interest = 'Pending';
let summary = '';
let extracted_name = '';
let extracted_email = '';
let extracted_phone = '';
let extracted_service_type = '';

try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);
  reply = parsed.reply || '';
  interest = parsed.interest || 'Pending';
  summary = parsed.summary || '';
  extracted_name = parsed.extracted_name || '';
  extracted_email = parsed.extracted_email || '';
  extracted_phone = (parsed.extracted_phone || '').replace(/\D/g, '');
  extracted_service_type = parsed.extracted_service_type || '';
} catch (e) {
  try {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      reply = parsed.reply || '';
      interest = parsed.interest || 'Pending';
      summary = parsed.summary || '';
      extracted_name = parsed.extracted_name || '';
      extracted_email = parsed.extracted_email || '';
      extracted_phone = (parsed.extracted_phone || '').replace(/\D/g, '');
      extracted_service_type = parsed.extracted_service_type || '';
    }
  } catch (e2) {}
}

if (!reply) {
  reply = raw.replace(/```[\s\S]*?```/g, '').trim();
  if (!reply) reply = 'Thanks for reaching out! How can I help you today?';
}

const finalName = extracted_name || base.contactName;
const finalEmail = extracted_email || base.contactEmail;
const finalPhone = extracted_phone || base.contactPhone;
const finalService = extracted_service_type || base.serviceType;

return [{ json: {
  ...base,
  reply,
  interest,
  summary,
  extracted_name,
  extracted_email,
  extracted_phone,
  extracted_service_type,
  finalName,
  finalEmail,
  finalPhone,
  finalService
} }];

const customerMsg = $('Extract DM Data').first().json.userMessage || '';
const agentMsg = $('Parse Reply').first().json.reply || '';

const newChatBlock = `Customer: ${customerMsg}\nAgent: ${agentMsg}\n------------------------`;

return [{
  json: {
    ...$('Parse Reply').first().json,
    newChatBlock
  }
}];
